window.START_COURSES.find(c=>c.id==="formacao-freudiana").modules.push({"id":"freud_m07","title":"Freud [1932–1940]","description":"Revisões finais, limites do tratamento e os últimos trabalhos. O recorte alcança 1940 por publicação póstuma, embora Freud tenha morrido em 1939.","lessons":[{"id":"freud_a144","title":"Novas Conferências Introdutórias #1","minutes":18,"hook":"Qual é o problema teórico por trás de “continuidade e mudança desde 1917” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “continuidade e mudança desde 1917”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Novas conferências introdutórias, publicadas em 1933, revisitam e desenvolvem temas apresentados no ciclo anterior, com questões de sonhos, estrutura psíquica, feminilidade e mundo cultural. Foram escritas para leitura, não uma simples repetição das conferências de 1916–1917."},{"title":"Entenda o conceito: Continuidade e mudança desde 1917","body":"Compare a apresentação do inconsciente e dos sonhos com as conferências antigas. Observe os efeitos da segunda tópica e das reformulações das pulsões.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O valor didático está na comparação: a teoria se transforma e certas perguntas permanecem abertas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “continuidade e mudança desde 1917”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Um professor percebe que sua explicação de 1917 não daria conta de dúvidas de 1933. A revisão é um sinal de desenvolvimento teórico, não de fraqueza intelectual.\n\nAgora retome o foco desta aula: continuidade e mudança desde 1917. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Novas conferências","desc":"Obra de 1933 que atualiza e amplia tópicos de introdução à psicanálise."},{"term":"Segunda tópica","desc":"Modelo de isso, eu e supereu formulado por Freud em 1923."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “continuidade e mudança desde 1917” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1933, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Continuidade e mudança desde 1917” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1933) — Novas Conferências Introdutórias. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a145","title":"Novas Conferências Introdutórias #2","minutes":15,"hook":"Qual é o problema teórico por trás de “conceitos tardios e problemas da época” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “conceitos tardios e problemas da época”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"As Novas conferências introdutórias, publicadas em 1933, revisitam e desenvolvem temas apresentados no ciclo anterior, com questões de sonhos, estrutura psíquica, feminilidade e mundo cultural. Foram escritas para leitura, não uma simples repetição das conferências de 1916–1917."},{"title":"Entenda o conceito: Conceitos tardios e problemas da época","body":"Freud aborda angústia, funcionamento psíquico e sexualidade em formulações marcadas por pressupostos históricos. Uma leitura crítica pode reconhecer inovação e preconceitos do período.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O valor didático está na comparação: a teoria se transforma e certas perguntas permanecem abertas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “conceitos tardios e problemas da época”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Um professor percebe que sua explicação de 1917 não daria conta de dúvidas de 1933. A revisão é um sinal de desenvolvimento teórico, não de fraqueza intelectual.\n\nAgora retome o foco desta aula: conceitos tardios e problemas da época. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Novas conferências","desc":"Obra de 1933 que atualiza e amplia tópicos de introdução à psicanálise."},{"term":"Segunda tópica","desc":"Modelo de isso, eu e supereu formulado por Freud em 1923."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “conceitos tardios e problemas da época” nesta obra?","options":["Examinar o argumento no contexto de 1933, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Conceitos tardios e problemas da época” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1933) — Novas Conferências Introdutórias. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a146","title":"A sutileza de um ato falho - 1935","minutes":18,"hook":"Qual é o problema teórico por trás de “o minúsculo e o interpretável” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o minúsculo e o interpretável”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Neste pequeno texto, Freud retoma o interesse pelos erros cotidianos para propor uma interpretação delicada de um ato falho. Seu valor formativo está em observar como hipóteses são construídas a partir de detalhes e associações, mas sem supor que toda falha seja passível de explicação inequívoca."},{"title":"Entenda o conceito: O minúsculo e o interpretável","body":"O texto permite perguntar que diferença existe entre notar um detalhe e afirmar que se conhece sua causa. É preciso privilegiar contexto, múltiplas hipóteses e limites da interpretação. A exatidão narrativa de um caso não constitui prova geral de um mecanismo.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Volte à Psicopatologia da vida cotidiana e compare o argumento tardio com as primeiras formulações sobre lapsos."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o minúsculo e o interpretável”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma troca de envelope pode ter ocorrido por desatenção. Antes de dizer 'o inconsciente escolheu', pergunte o que se sabe realmente sobre circunstâncias e associações.\n\nAgora retome o foco desta aula: o minúsculo e o interpretável. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Ato falho","desc":"Deslize ou erro cotidiano considerado por Freud em relação a processos psíquicos possíveis."},{"term":"Hipótese interpretativa","desc":"Proposição sujeita a revisão e dependente da evidência disponível."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o minúsculo e o interpretável” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1935, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “O minúsculo e o interpretável” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1935) — A sutileza de um ato falho - 1935. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a147","title":"Um Distúrbio de Memória na Acrópole","minutes":18,"hook":"Qual é o problema teórico por trás de “estranhamento, memória e realização” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “estranhamento, memória e realização”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud descreve uma experiência de estranhamento durante visita à Acrópole e tenta pensá-la em relação a afetos, realização de desejo e vínculos familiares. O ensaio não fornece um diagnóstico universal de despersonalização ou dissociação; trata-se de reflexão autobiográfica e interpretação retrospectiva."},{"title":"Entenda o conceito: Estranhamento, memória e realização","body":"O autor examina o contraste entre algo que sabe e a impressão de irrealidade diante de uma experiência real. A leitura põe em jogo memória, desejo e história pessoal, ao mesmo tempo que destaca limites de uma interpretação feita anos depois.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare o pequeno ensaio com estudos sobre memória e com textos autobiográficos, separando descrição fenomenológica de teoria explicativa."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “estranhamento, memória e realização”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa visita uma cidade desejada e comenta: 'Não acredito que estou aqui'. A frase comum não implica, por si só, uma alteração clínica da realidade.\n\nAgora retome o foco desta aula: estranhamento, memória e realização. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Estranhamento","desc":"Experiência de surpresa ou deslocamento na relação com algo vivido, com diferentes usos descritivos e clínicos."},{"term":"Acrópole","desc":"Local da experiência autobiográfica narrada por Freud em ensaio de 1936."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “estranhamento, memória e realização” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1936, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Estranhamento, memória e realização” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1936) — Um Distúrbio de Memória na Acrópole. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a148","title":"Construções em Análise #1","minutes":18,"hook":"Qual é o problema teórico por trás de “construção e interpretação” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “construção e interpretação”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1937, Freud examina a tarefa de reconstruir aspectos da história psíquica quando não há lembranças completas. A construção é uma hipótese trabalhada no tratamento, não licença para fabricar lembranças nem declarar um acontecimento factual verdadeiro sem evidência."},{"title":"Entenda o conceito: Construção e interpretação","body":"Freud diferencia modos de trabalho com elementos dispersos da fala e com conexões possíveis. O valor de uma construção se discute por seus efeitos no processo, sem convertê-la em prova documental.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto dialoga com sonhos, casos clínicos e com o problema ético das falsas memórias. Uma hipótese pode ser abandonada quando não ajuda ou não se sustenta.\n\nNota ética: evitar produzir ou reforçar memórias sugeridas como se fossem fatos verificados."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “construção e interpretação”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa recorda um ambiente assustador da infância, mas não sabe explicar por quê. O profissional não deve sugerir acontecimentos específicos como se tivessem sido descobertos.\n\nAgora retome o foco desta aula: construção e interpretação. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Construção","desc":"Hipótese clínica que organiza elementos da história psíquica; não equivale à comprovação factual."},{"term":"Interpretação","desc":"Intervenção relativa a sentidos e relações do material emergente no processo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “construção e interpretação” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1937, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Construção e interpretação” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1937) — Construções em Análise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a149","title":"Construções em Análise #2","minutes":15,"hook":"Qual é o problema teórico por trás de “como trabalhar com o incerto” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “como trabalhar com o incerto”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Em 1937, Freud examina a tarefa de reconstruir aspectos da história psíquica quando não há lembranças completas. A construção é uma hipótese trabalhada no tratamento, não licença para fabricar lembranças nem declarar um acontecimento factual verdadeiro sem evidência."},{"title":"Entenda o conceito: Como trabalhar com o incerto","body":"O analista deve suportar limites de memória e de verificabilidade. A elaboração clínica pode produzir sentidos relevantes sem estabelecer com certeza todos os acontecimentos passados.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"O texto dialoga com sonhos, casos clínicos e com o problema ético das falsas memórias. Uma hipótese pode ser abandonada quando não ajuda ou não se sustenta.\n\nNota ética: evitar produzir ou reforçar memórias sugeridas como se fossem fatos verificados."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “como trabalhar com o incerto”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa recorda um ambiente assustador da infância, mas não sabe explicar por quê. O profissional não deve sugerir acontecimentos específicos como se tivessem sido descobertos.\n\nAgora retome o foco desta aula: como trabalhar com o incerto. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Construção","desc":"Hipótese clínica que organiza elementos da história psíquica; não equivale à comprovação factual."},{"term":"Interpretação","desc":"Intervenção relativa a sentidos e relações do material emergente no processo."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “como trabalhar com o incerto” nesta obra?","options":["Examinar o argumento no contexto de 1937, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Como trabalhar com o incerto” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1937) — Construções em Análise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a150","title":"Análise Terminável e Interminável #1","minutes":18,"hook":"Qual é o problema teórico por trás de “quando um trabalho pode terminar?” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “quando um trabalho pode terminar?”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud discute limites da ação terapêutica, dificuldades técnicas, duração de tratamentos e persistência de conflitos. O texto é decisivo para abandonar a fantasia de que análise garanta a completa eliminação de sofrimento ou leve a uma personalidade 'sem inconsciente'."},{"title":"Entenda o conceito: Quando um trabalho pode terminar?","body":"Freud analisa possibilidades e condições de encerramento, sem estabelecer uma fórmula universal. A decisão envolve objetivos, transformação possível, circunstâncias e responsabilidade clínica.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare com o texto sobre o percurso analítico, com Recordar, repetir e elaborar e com Construções em análise."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “quando um trabalho pode terminar?”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa decide encerrar análise após atingir objetivos importantes. Isso não exige dizer que ela 'resolveu tudo' ou que qualquer conflito futuro provará fracasso.\n\nAgora retome o foco desta aula: quando um trabalho pode terminar?. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Fim de análise","desc":"Questão clínica e teórica sobre critérios e possibilidades de encerramento do processo."},{"term":"Limites do tratamento","desc":"Reconhecimento de que a análise não produz transformação ilimitada ou universal."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “quando um trabalho pode terminar?” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1937, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Quando um trabalho pode terminar?” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1937) — Análise Terminável e Interminável. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a151","title":"Análise Terminável e Interminável #2","minutes":15,"hook":"Qual é o problema teórico por trás de “limites, resistência e formação do analista” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “limites, resistência e formação do analista”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud discute limites da ação terapêutica, dificuldades técnicas, duração de tratamentos e persistência de conflitos. O texto é decisivo para abandonar a fantasia de que análise garanta a completa eliminação de sofrimento ou leve a uma personalidade 'sem inconsciente'."},{"title":"Entenda o conceito: Limites, resistência e formação do analista","body":"O texto volta a discutir como conflitos do próprio analista e limites de técnica podem interferir na prática. A leitura não autoriza culpar exclusivamente o paciente quando um tratamento não avança.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Compare com o texto sobre o percurso analítico, com Recordar, repetir e elaborar e com Construções em análise."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “limites, resistência e formação do analista”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa decide encerrar análise após atingir objetivos importantes. Isso não exige dizer que ela 'resolveu tudo' ou que qualquer conflito futuro provará fracasso.\n\nAgora retome o foco desta aula: limites, resistência e formação do analista. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Fim de análise","desc":"Questão clínica e teórica sobre critérios e possibilidades de encerramento do processo."},{"term":"Limites do tratamento","desc":"Reconhecimento de que a análise não produz transformação ilimitada ou universal."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “limites, resistência e formação do analista” nesta obra?","options":["Examinar o argumento no contexto de 1937, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Limites, resistência e formação do analista” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1937) — Análise Terminável e Interminável. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a152","title":"A Divisão do Eu no Processo Defensivo #1","minutes":18,"hook":"Qual é o problema teórico por trás de “desmentido e coexistência de atitudes” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “desmentido e coexistência de atitudes”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Escrito em 1938 e publicado postumamente em 1940, o ensaio aborda a divisão do eu em determinada organização defensiva. É especialmente importante diferenciar Verleugnung (desmentido/recusa) de Verdrängung (recalque), respeitando debates de tradução e desenvolvimento da teoria."},{"title":"Entenda o conceito: Desmentido e coexistência de atitudes","body":"Freud analisa como posições contraditórias podem coexistir diante de uma experiência. O modelo não deve servir para chamar qualquer contradição cotidiana de 'cisão patológica'.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Conecte com O eu e o id, Fetichismo (1927) e Esboço da psicanálise, marcando diferenças entre versões do conceito.\n\nNota cronológica: escrito em 1938; publicado após a morte de Freud, em 1940."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “desmentido e coexistência de atitudes”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sustenta opiniões diferentes em contextos distintos. Isso não basta para aplicar o conceito técnico de divisão do eu.\n\nAgora retome o foco desta aula: desmentido e coexistência de atitudes. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Divisão do eu (Ichspaltung)","desc":"Formulação de Freud sobre coexistência de atitudes psíquicas em processos defensivos."},{"term":"Desmentido (Verleugnung)","desc":"Conceito defensivo a distinguir do recalque (Verdrängung)."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “desmentido e coexistência de atitudes” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1940 [redigido em 1938], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Desmentido e coexistência de atitudes” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1940 [redigido em 1938]) — A Divisão do Eu no Processo Defensivo. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a153","title":"A Divisão do Eu no Processo Defensivo #2","minutes":15,"hook":"Qual é o problema teórico por trás de “diferenças entre defesa, recalque e cisão” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “diferenças entre defesa, recalque e cisão”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Escrito em 1938 e publicado postumamente em 1940, o ensaio aborda a divisão do eu em determinada organização defensiva. É especialmente importante diferenciar Verleugnung (desmentido/recusa) de Verdrängung (recalque), respeitando debates de tradução e desenvolvimento da teoria."},{"title":"Entenda o conceito: Diferenças entre defesa, recalque e cisão","body":"O texto complica uma imagem unitária do eu e exige precisão terminológica. A noção de cisão será trabalhada de outras formas por psicanalistas posteriores, que não devem ser fundidas automaticamente.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Conecte com O eu e o id, Fetichismo (1927) e Esboço da psicanálise, marcando diferenças entre versões do conceito.\n\nNota cronológica: escrito em 1938; publicado após a morte de Freud, em 1940."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “diferenças entre defesa, recalque e cisão”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma pessoa sustenta opiniões diferentes em contextos distintos. Isso não basta para aplicar o conceito técnico de divisão do eu.\n\nAgora retome o foco desta aula: diferenças entre defesa, recalque e cisão. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Divisão do eu (Ichspaltung)","desc":"Formulação de Freud sobre coexistência de atitudes psíquicas em processos defensivos."},{"term":"Desmentido (Verleugnung)","desc":"Conceito defensivo a distinguir do recalque (Verdrängung)."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “diferenças entre defesa, recalque e cisão” nesta obra?","options":["Examinar o argumento no contexto de 1940 [redigido em 1938], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Diferenças entre defesa, recalque e cisão” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1940 [redigido em 1938]) — A Divisão do Eu no Processo Defensivo. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a154","title":"O Esboço da Psicanálise #1","minutes":18,"hook":"Qual é o problema teórico por trás de “panorama do aparelho psíquico” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “panorama do aparelho psíquico”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud redige em 1938 uma apresentação de suas teses centrais, publicada postumamente como Esboço da psicanálise. O texto permite ver seu pensamento em fase tardia: modelos do aparelho, pulsões, desenvolvimento e técnica coexistem com revisões e tensões não resolvidas."},{"title":"Entenda o conceito: Panorama do aparelho psíquico","body":"O esboço retoma isso, eu e supereu como modos de organizar problemas. Um esquema simplificado não deve ser confundido com desenho de estruturas do cérebro.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"É uma excelente leitura de encerramento do percurso: volte às primeiras obras e identifique continuidades e mudanças, sem forçar coerência perfeita.\n\nNota cronológica: o manuscrito é de 1938 e a publicação é póstuma (1940)."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “panorama do aparelho psíquico”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se alguém compara um texto de 1895 com um resumo de 1938, encontrará termos semelhantes com funções diferentes. A aprendizagem está em reconstruir a transformação, não em fingir uniformidade.\n\nAgora retome o foco desta aula: panorama do aparelho psíquico. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Esboço da psicanálise","desc":"Síntese tardia de Freud, escrita em 1938 e publicada postumamente."},{"term":"Metapsicologia","desc":"Conjunto de modelos conceituais para pensar funcionamento e conflito psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “panorama do aparelho psíquico” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1940 [escrito em 1938], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “Panorama do aparelho psíquico” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1940 [escrito em 1938]) — O Esboço da Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a155","title":"O Esboço da Psicanálise #2","minutes":15,"hook":"Qual é o problema teórico por trás de “pulsões e desenvolvimento” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “pulsões e desenvolvimento”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud redige em 1938 uma apresentação de suas teses centrais, publicada postumamente como Esboço da psicanálise. O texto permite ver seu pensamento em fase tardia: modelos do aparelho, pulsões, desenvolvimento e técnica coexistem com revisões e tensões não resolvidas."},{"title":"Entenda o conceito: Pulsões e desenvolvimento","body":"Freud sintetiza teorias da libido, das identificações e do conflito, com pressupostos que devem ser confrontados com críticas históricas posteriores.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"É uma excelente leitura de encerramento do percurso: volte às primeiras obras e identifique continuidades e mudanças, sem forçar coerência perfeita.\n\nNota cronológica: o manuscrito é de 1938 e a publicação é póstuma (1940)."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “pulsões e desenvolvimento”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se alguém compara um texto de 1895 com um resumo de 1938, encontrará termos semelhantes com funções diferentes. A aprendizagem está em reconstruir a transformação, não em fingir uniformidade.\n\nAgora retome o foco desta aula: pulsões e desenvolvimento. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Esboço da psicanálise","desc":"Síntese tardia de Freud, escrita em 1938 e publicada postumamente."},{"term":"Metapsicologia","desc":"Conjunto de modelos conceituais para pensar funcionamento e conflito psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “pulsões e desenvolvimento” nesta obra?","options":["Examinar o argumento no contexto de 1940 [escrito em 1938], distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto."],"correct":0,"feedback":"O tópico “Pulsões e desenvolvimento” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1940 [escrito em 1938]) — O Esboço da Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a156","title":"O Esboço da Psicanálise #3","minutes":15,"hook":"Qual é o problema teórico por trás de “o tratamento e seus limites” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “o tratamento e seus limites”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Freud redige em 1938 uma apresentação de suas teses centrais, publicada postumamente como Esboço da psicanálise. O texto permite ver seu pensamento em fase tardia: modelos do aparelho, pulsões, desenvolvimento e técnica coexistem com revisões e tensões não resolvidas."},{"title":"Entenda o conceito: O tratamento e seus limites","body":"O texto apresenta princípios do trabalho analítico sem cancelar dificuldades e incertezas examinadas no mesmo período. A clínica contemporânea precisa dialogar com evidências e normas éticas adicionais.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"É uma excelente leitura de encerramento do percurso: volte às primeiras obras e identifique continuidades e mudanças, sem forçar coerência perfeita.\n\nNota cronológica: o manuscrito é de 1938 e a publicação é póstuma (1940)."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “o tratamento e seus limites”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Se alguém compara um texto de 1895 com um resumo de 1938, encontrará termos semelhantes com funções diferentes. A aprendizagem está em reconstruir a transformação, não em fingir uniformidade.\n\nAgora retome o foco desta aula: o tratamento e seus limites. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Esboço da psicanálise","desc":"Síntese tardia de Freud, escrita em 1938 e publicada postumamente."},{"term":"Metapsicologia","desc":"Conjunto de modelos conceituais para pensar funcionamento e conflito psíquico."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “o tratamento e seus limites” nesta obra?","options":["Tomar qualquer caso citado como demonstração de uma lei psicológica universal.","Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1940 [escrito em 1938], distinguindo hipótese, exemplos e limites da interpretação."],"correct":2,"feedback":"O tópico “O tratamento e seus limites” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1940 [escrito em 1938]) — O Esboço da Psicanálise. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]},{"id":"freud_a157","title":"Moisés e o Monoteísmo #1","minutes":18,"hook":"Qual é o problema teórico por trás de “história, memória coletiva e conjectura” — e por que não basta decorar sua definição?","lead":"Nesta aula de leitura, o foco é “história, memória coletiva e conjectura”. Vamos situar o problema no pensamento freudiano, explicitar o raciocínio e observar os limites de sua utilização clínica. O conteúdo abaixo é uma elaboração didática original a partir do tema do texto — não é uma transcrição de aulas de terceiros.","blocks":[{"title":"Antes de interpretar: situação histórica","body":"Publicado em 1939, Moisés e o monoteísmo reúne especulações histórico-psicanalíticas sobre religião, tradição, identidade e transmissão. As hipóteses de Freud sobre eventos antigos são altamente controversas e não devem ser apresentadas como consenso historiográfico nem como conclusão sobre o judaísmo ou qualquer religião."},{"title":"Entenda o conceito: História, memória coletiva e conjectura","body":"Freud explora como narrativas e identidades coletivas poderiam ser organizadas por acontecimentos, conflitos e repetições. Separar interpretação psicanalítica, hipótese histórica e documentação é essencial, especialmente num tema afetado pelo contexto de perseguição antissemita na Europa.\n\nRepare que esse recorte não esgota a obra. O exercício aqui é distinguir o que Freud descreve, a interpretação que propõe e o que permanece em aberto. Quando uma hipótese for construída sobre observações clínicas, não a trate automaticamente como regra para toda pessoa ou período histórico."},{"title":"Articulações, controvérsias e limites","body":"Relacione com Totem e tabu, Futuro de uma ilusão e Psicologia das massas. O debate histórico não pode ser resolvido apenas por categorias clínicas.\n\nO sumário enviado mostra apenas “Moisés e o Monoteísmo #1”; outras possíveis partes não foram inventadas."},{"title":"Roteiro de estudo ativo","body":"1. Abra o texto de Freud indicado nas referências e localize os argumentos relacionados a “história, memória coletiva e conjectura”.\n\n2. Escreva com suas palavras a pergunta que motivou o argumento e a resposta provisória oferecida por Freud.\n\n3. Marque uma hipótese e uma observação: elas têm o mesmo estatuto?\n\n4. Compare sua resposta com a seção anterior e registre na área de anotações uma dúvida para retomar mais tarde."}],"example":{"title":"Situação para pensar, sem diagnosticar","body":"Uma comunidade preserva narrativas sobre sua origem. Elas podem ter funções simbólicas complexas sem que a psicanálise determine qual versão dos acontecimentos é factual.\n\nAgora retome o foco desta aula: história, memória coletiva e conjectura. Que novas perguntas ele permite formular sem oferecer uma resposta pronta?"},"terms":[{"term":"Monoteísmo","desc":"Crença em uma divindade, cujo estudo histórico e religioso não se reduz à teoria freudiana."},{"term":"Memória coletiva","desc":"Campo de estudos sobre a transmissão de narrativas e pertencimentos entre grupos."}],"quiz":{"question":"Qual cuidado é essencial ao estudar “história, memória coletiva e conjectura” nesta obra?","options":["Usar o conceito como diagnóstico imediato de pessoas reais, dispensando associações e contexto.","Examinar o argumento no contexto de 1939, distinguindo hipótese, exemplos e limites da interpretação.","Tomar qualquer caso citado como demonstração de uma lei psicológica universal."],"correct":1,"feedback":"O tópico “História, memória coletiva e conjectura” exige localizar a hipótese no texto, acompanhar sua construção e reconhecer o que ela não demonstra. A formulação histórica não substitui avaliação clínica atual."},"refs":["Freud (1939) — Moisés e o Monoteísmo. Verifique a tradução e a edição utilizada.","Freud, S. — Obras completas; compare a organização cronológica e notas editoriais da edição consultada."]}]});
